create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan text not null check(plan in('pro','business')),amount_rial bigint not null check(amount_rial>0),status text not null default 'awaiting_payment' check(status in('awaiting_payment','pending_review','paid','rejected','cancelled')),gateway text not null default 'card_transfer',payment_identifier text,reference text,note text,submitted_at timestamptz,paid_at timestamptz,reviewed_at timestamptz,reviewed_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan text not null check(plan in('pro','business')),status text not null default 'active' check(status in('active','expired','cancelled')),started_at timestamptz default now(),expires_at timestamptz not null,gateway text not null default 'card_transfer',payment_id uuid references public.payments(id),created_at timestamptz default now());
create index if not exists payments_user_idx on public.payments(user_id,created_at desc);
create index if not exists subs_user_idx on public.subscriptions(user_id,expires_at desc);
alter table public.profiles enable row level security;alter table public.payments enable row level security;alter table public.subscriptions enable row level security;
drop policy if exists "profiles own select" on public.profiles;create policy "profiles own select" on public.profiles for select to authenticated using((select auth.uid())=id);
drop policy if exists "profiles own update" on public.profiles;create policy "profiles own update" on public.profiles for update to authenticated using((select auth.uid())=id);
drop policy if exists "payments own select" on public.payments;create policy "payments own select" on public.payments for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "subscriptions own select" on public.subscriptions;create policy "subscriptions own select" on public.subscriptions for select to authenticated using((select auth.uid())=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name,phone) values(new.id,new.raw_user_meta_data->>'full_name',new.phone) on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
